package com.leetcode.backend.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="assessment_invitations",uniqueConstraints=@UniqueConstraint(columnNames={"assessment_id","user_id"}),indexes={@Index(name="idx_assessment_invitation_user",columnList="user_id,assessment_id"),@Index(name="idx_assessment_invitation_status",columnList="assessment_id,status")}) public class AssessmentInvitation {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="assessment_id",nullable=false) private Assessment assessment; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="invited_by_creator_id") private User invitedByCreator; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private AssessmentEnums.InvitationStatus status=AssessmentEnums.InvitationStatus.INVITED; @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @Column(name="invited_at",nullable=false) private LocalDateTime invitedAt; @Column(name="email_sent_at") private LocalDateTime emailSentAt; @Column(name="registered_at") private LocalDateTime registeredAt; @Column(name="access_token_hash",length=100) private String accessTokenHash; @Column(name="access_token_expires_at") private LocalDateTime accessTokenExpiresAt; @PrePersist void create(){LocalDateTime now=LocalDateTime.now();createdAt=now;invitedAt=now;} public Long getId(){return id;} public Assessment getAssessment(){return assessment;} public void setAssessment(Assessment v){assessment=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public User getInvitedByCreator(){return invitedByCreator;} public void setInvitedByCreator(User v){invitedByCreator=v;} public AssessmentEnums.InvitationStatus getStatus(){return status;} public void setStatus(AssessmentEnums.InvitationStatus v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getInvitedAt(){return invitedAt;} public LocalDateTime getEmailSentAt(){return emailSentAt;} public void setEmailSentAt(LocalDateTime v){emailSentAt=v;} public LocalDateTime getRegisteredAt(){return registeredAt;} public void setRegisteredAt(LocalDateTime v){registeredAt=v;} public String getAccessTokenHash(){return accessTokenHash;} public void setAccessTokenHash(String v){accessTokenHash=v;} public LocalDateTime getAccessTokenExpiresAt(){return accessTokenExpiresAt;} public void setAccessTokenExpiresAt(LocalDateTime v){accessTokenExpiresAt=v;}
}
